## 3.  C++

```cpp
#include <vector>
#include <stdexcept>
#include <iostream>

int majorityElement(const std::vector<int>& nums) {
    // Phase 1: Find a candidate
    int candidate = 0;
    int count = 0;
    for (int num : nums) {
        if (count == 0) {
            candidate = num;
            count = 1;
        } else if (num == candidate) {
            ++count;
        } else {
            --count;
        }
    }

    // Phase 2: (Optional) Verify
    // int occurrences = 0;
    // for (int num : nums) if (num == candidate) ++occurrences;
    // if (occurrences <= nums.size() / 2) throw std::runtime_error("No majority element");

    return candidate;
}

int main() {
    std::vector<int> arr = {2, 2, 1, 1, 1, 2, 2};
    std::cout << majorityElement(arr) << std::endl;  // prints 2
}
```

